CREATE TABLE service_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), version INTEGER NOT NULL, title TEXT NOT NULL, audience TEXT NOT NULL, deliverables TEXT NOT NULL, rights TEXT NOT NULL, deadline TEXT, status TEXT NOT NULL CHECK(status IN ('received','qualified','quoted','contracted','fulfilling','delivered','closed')), assigned_to TEXT REFERENCES users(id), due_at TEXT, quote_note TEXT NOT NULL, contract_id TEXT REFERENCES contracts(id), order_id TEXT REFERENCES orders(id), evidence TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX service_request_owner ON service_requests(user_id,updated_at);
